   use tl_model::validity::Validity;

   #[derive(Debug, thiserror::Error)]
   pub enum CollectError {
       #[error("permission denied")]
       PermissionDenied,                 // EACCES, EPERM
       #[error("not found")]
       NotFound,                         // ENOENT, ESRCH, ENODEV, ENXIO
       #[error("os error {0}")]
       Os(rustix::io::Errno),            // any other errno
       #[error("cannot parse {file}: {what}")]
       Parse { file: &'static str, what: &'static str },
   }

   impl From<rustix::io::Errno> for CollectError { /* mapping above */ }
   impl From<std::io::Error> for CollectError {
       // raw_os_error() Some(n) -> From<Errno>(Errno::from_raw_os_error(n)); None -> Os(Errno::IO)
   }
   impl CollectError {
       /// The Validity a field gets when reading it failed with this error (ADR-016).
       pub fn validity(&self) -> Validity {
