```rust
use tl_model::{series::SampleFlags, time::{now_boot_ns, now_mono_ns, TimeNs}, validity::Validity};

/// Suspend check: (Δboot - Δmono) above this means the machine slept (ADR-008, R-051).
pub const SUSPEND_GAP_NS: u64 = 250_000_000;
/// Lower bound of the stale threshold: max(3 × period, 1.5 s) (ADR-008).
pub const STALE_FLOOR_NS: u64 = 1_500_000_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Clock { pub boot_ns: TimeNs, pub mono_ns: u64 }
impl Clock {
    /// Reads CLOCK_BOOTTIME then CLOCK_MONOTONIC. Call immediately before the read syscalls.
    pub fn now() -> Self;
}

/// True when the boottime delta exceeds the monotonic delta by more than 250 ms.
pub fn resumed_between(prev: Clock, cur: Clock) -> bool;
/// True when now - last > max(3 × period, 1.5 s). Saturating arithmetic.
pub fn is_stale(now_ns: TimeNs, last_ns: TimeNs, period_ns: u64) -> bool;

/// A value with its Validity. Missing data is never zero (ADR-003).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Measured<T> { pub value: T, pub validity: Validity }
impl<T> Measured<T> { pub fn valid(value: T) -> Self; }
impl<T: Default> Measured<T> { pub fn invalid(validity: Validity) -> Self; }   // value = T::default()
impl<T: Default> Default for Measured<T> { fn default() -> Self { Self::invalid(Validity::WarmingUp) } }

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rate { pub per_sec: f64, pub validity: Validity, pub flags: SampleFlags }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Delta { Ok { delta: u64, dt_ns: u64 }, WarmingUp { flags: SampleFlags } }

/// One cumulative u64 counter.
#[derive(Clone, Copy, Debug, Default)]
pub struct Counter { prev: Option<(u64, TimeNs, u32)> }   // (value, t_ns, generation)
impl Counter {
    pub fn step(&mut self, cur: u64, t_ns: TimeNs, generation: u32) -> Delta;
    /// Like `step` but a decrease is a wrap at `max_range` (RAPL `max_energy_range_uj`).
    pub fn step_wrapping(&mut self, cur: u64, t_ns: TimeNs, generation: u32, max_range: u64) -> Delta;
    pub fn update(&mut self, cur: u64, t_ns: TimeNs, generation: u32) -> Rate;
    pub fn update_wrapping(&mut self, cur: u64, t_ns: TimeNs, generation: u32, max_range: u64) -> Rate;
    /// Forget the baseline (resume, ResetBaselines, rate change). Next step is WarmingUp.
    pub fn reset(&mut self);
}

/// 100 × num / den clamped to 0..=100; None when den == 0.
pub fn ratio_pct(num: u64, den: u64) -> Option<f32>;
```
Rules for `step`, in order. Every case stores `(cur, t_ns, generation)` as the new baseline:
1. No baseline: `WarmingUp { flags: empty }`.
2. `generation` differs from the baseline's: `WarmingUp { flags: GAP_BEFORE }`.
3. `t_ns <= baseline t`: `WarmingUp { flags: empty }`.
4. `cur < baseline value`: `WarmingUp { flags: RESET }` (`step_wrapping`: if `max_range > baseline value`, instead `Ok { delta: cur + (max_range - prev), .. }`).
5. Otherwise `Ok { delta: cur - prev, dt_ns: t_ns - t_prev }`.

`update` maps `Ok` to `Rate { per_sec: delta as f64 / (dt_ns as f64 / 1e9), validity: Valid, flags: VALID }` and `WarmingUp { flags }` to `Rate { per_sec: 0.0, validity: WarmingUp, flags }` (VALID clear). `reset()` sets the baseline to `None`.

## Acceptance Criteria
- **Given** a new `Counter` **When** `update(100, 1_000_000_000, 0)` runs **Then** validity is `WarmingUp` and flags are empty.
- **Given** baseline (100, 1 s, gen 0) **When** `update(1100, 1.5 s, 0)` **Then** `per_sec == 2000.0`, `Valid`, flags `VALID`.
- **Given** baseline (1000, 1 s, 0) **When** `update(10, 2 s, 0)` **Then** `WarmingUp` with flag `RESET`; **When** then `update(20, 3 s, 0)` **Then** `per_sec == 10.0`.
- **Given** baseline at generation 0 **When** `update(..., generation 1)` **Then** `WarmingUp` with `GAP_BEFORE`.
- **Given** baseline at t = 2 s **When** `update(.., t = 2 s, ..)` **Then** `WarmingUp`, no panic, no division by zero.
- **Given** baseline (900, 1 s) **When** `step_wrapping(100, 2 s, 0, 1000)` **Then** `Ok { delta: 200, dt_ns: 1_000_000_000 }`.
- **Given** a `reset()` after a valid baseline **When** `update` runs **Then** `WarmingUp`.
- **Given** prev clock (boot 0, mono 0) and cur clock (boot 5 s, mono 10 ms) **When** `resumed_between` **Then** true (ADR-008 verification case).
- **Given** a boot delta 200 ms larger than the mono delta **Then** false; exactly 250 ms larger **Then** false; 251 ms **Then** true.
