pub struct SysQuery {
    current: SysTableQuery,   // tl_model::table::SysTableQuery
    last_sent: u64,           // generation of the last query handed to EngineClient::send
    pending_resend: bool,     // true when the last send returned Err(CommandError::Busy)
}

impl SysQuery {
    pub fn new(table: SysTable, sort: SortSpec, services: Option<ServiceFilter>) -> Self;
    pub fn query(&self) -> &SysTableQuery;
    pub fn last_sent(&self) -> u64;
    /// Lowercases `text` (str::to_lowercase), stores it as Arc<str>, bumps generation, sends.
    pub fn set_filter(&mut self, text: &str, client: &dyn EngineClient);
    pub fn set_sort(&mut self, sort: SortSpec, client: &dyn EngineClient);
    pub fn set_expanded(&mut self, expanded: Arc<[SysNodeId]>, client: &dyn EngineClient);
    pub fn set_services_filter(&mut self, f: ServiceFilter, client: &dyn EngineClient);
    /// Sends the current query again with a new generation (used after Busy and on first visit).
    pub fn resend(&mut self, client: &dyn EngineClient);
    /// Call on every snapshot install: resends once if `pending_resend`.
    pub fn on_snapshot(&mut self, client: &dyn EngineClient);
    /// True when a view with this generation may be shown.
    pub fn accepts(&self, query_generation: u64) -> bool { query_generation == self.last_sent }
}

